def minimum_moves_for_nonnegative_prefix(nums):
    import heapq
    negatives=[];total=moves=0
    for value in nums:
        total+=value
        if value<0:heapq.heappush(negatives,value)
        if total<0:
            total-=heapq.heappop(negatives);moves+=1
    return moves

